/bin/zsh -lc "find .. -name AGENTS.md -print && printf '\\n--- quick sim tb ---\\n' && cat > tb.sv <<'EOF'
module tb;
  reg clk=0, rst=0, data=0;
  wire flag;
  TopModule dut(.clk(clk), .rst(rst), .data(data), .flag(flag));
  always #5 clk = ~clk;
  task step(input bit d);
    begin
      data = d;
      #10;
      "'$display("t=%0t data=%0b state=%0d flag=%0b", $time, data, dut.state, flag);
    end
  endtask
  initial begin
    $display("start");
    #2; rst=0; #8; rst=1;
    step(1); step(0); step(1); step(1); // 1011
    step(0); step(1); step(1); step(1); // 0111 -> second detection only once in 10110111
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

