/bin/zsh -lc "cat > ./tb_rand.sv <<'EOF'
module tb;
  reg clk=0, rst=0, data=0;
  wire flag;
  reg [3:0] hist;
  reg ref_flag;
  integer i;

  TopModule dut(.clk(clk), .rst(rst), .data(data), .flag(flag));
  always #5 clk = ~clk;

  always @(posedge clk or negedge rst) begin
    if ("'!rst) begin
      hist <= 4'"'b0;
      ref_flag <= 1'b0;
    end else begin
      ref_flag <= (hist == 4'b1011);
      hist <= {hist[2:0], data};
    end
  end

  initial begin
    rst = 0;
    repeat (2) @(posedge clk);
    rst = 1;
    for (i = 0; i < 50; i = i + 1) begin
      data = "'$random;
      @(negedge clk);
      #1;
      if (flag !== ref_flag) begin
        $display("Mismatch at i=%0d data=%0b state=%0d hist=%b flag=%0b ref=%0b", i, data, dut.state, hist, flag, ref_flag);
        $finish;
      end
      @(posedge clk);
    end
    $display("PASS");
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv_rand TopModule.sv tb_rand.sv && vvp simv_rand'

